'use strict';
let correlationStart='',correlationEnd='',correlationTimer=null,correlationPair=null;
function correlationRange(){const all=timestamps(),from=correlationStart||all[0]?.slice(0,10)||'',to=correlationEnd||all.at(-1)?.slice(0,10)||'',start=Date.parse(from+'T00:00:00.000Z'),end=Date.parse(to+'T23:59:59.999Z');return {from,to,start,end,times:all.filter(t=>Date.parse(t)>=start&&Date.parse(t)<=end)};}
function stopCorrelations(){clearInterval(correlationTimer);correlationTimer=null;}
function pairedCorrelation(a,b){
  let n=0,mx=0,my=0,xx=0,yy=0,xy=0;const points=[];
  for(const [time,x] of a){const y=b.get(time);if(!Number.isFinite(x)||!Number.isFinite(y))continue;points.push([x,y]);n++;const dx=x-mx,dy=y-my;mx+=dx/n;my+=dy/n;xx+=dx*(x-mx);yy+=dy*(y-my);xy+=dx*(y-my);}
  const reason=n<3?'Fewer than 3 matched samples':xx<=0||yy<=0?'Constant variable':'';
  return {n,r:reason?null:Math.max(-1,Math.min(1,xy/Math.sqrt(xx*yy))),reason,points};
}
function correlationModel(){
  const range=correlationRange(),times=range.times,start=range.start,end=stamp?Math.min(Date.parse(stamp),range.end):Math.min(Date.parse(times.at(-1)),range.end),tags=new Map();
  for(const row of data.sensors){if(!tags.has(row.tag))tags.set(row.tag,{tag:row.tag,name:row.name||row.tag,unit:row.unit||'',values:new Map()});const t=Date.parse(row.timestamp);if(!Number.isFinite(t)||!Number.isFinite(end)||t<start||t>end)continue;const values=tags.get(row.tag).values;values.set(t,values.has(t)?null:typeof row.actual==='number'&&Number.isFinite(row.actual)?row.actual:null);}
  const variables=[...tags.values()],matrix=variables.map(()=>[]);
  for(let i=0;i<variables.length;i++)for(let j=i;j<variables.length;j++){const result=pairedCorrelation(variables[i].values,variables[j].values);matrix[i][j]=result;matrix[j][i]={...result,points:result.points.map(([x,y])=>[y,x])};}
  return {times,end,variables,matrix};
}
function correlationColor(r){if(r===null)return '#eef1f4';const target=r<0?[183,66,53]:[37,100,157],f=Math.abs(r);return `rgb(${target.map(v=>Math.round(249+(v-249)*f)).join(',')})`;}
function correlationsPage(){const range=correlationRange(),times=range.times,index=Math.max(0,times.indexOf(stamp||times.at(-1)));return heading('Correlations','Actual readings · Pearson correlation')+`<section class="panel"><div class="correlation-controls"><label>Start date (UTC) <input type="date" id="correlation-start" value="${esc(range.from)}" required></label><label>End date (UTC) <input type="date" id="correlation-end" value="${esc(range.to)}" required></label><button class="btn" id="correlation-play" ${times.length<2?'disabled':''}>${correlationTimer?'Pause':'Play recording'}</button><button class="btn" id="correlation-latest">End of range</button><label class="correlation-scrubber">Snapshot <input id="correlation-time" type="range" min="0" max="${Math.max(0,times.length-1)}" value="${index}" ${times.length?'':'disabled'}></label><span id="correlation-clock">${dateLabel(times[index])} UTC</span></div><p id="correlation-range-error" role="alert" class="correlation-note"></p><p class="correlation-note">${data.demo?'Demo':'Imported'} data · Date range includes both full days in UTC. Playback accumulates samples from the start date up to the selected snapshot; no live historian connection. Exact timestamp matches only; missing, invalid and duplicate readings are excluded per pair. At least 3 matched samples and variation in both tags are required. Correlation does not establish causation; shared trends can produce strong correlations.</p><div class="correlation-key"><span>−1 inverse</span><i></i><span>+1 together</span><span>— unavailable</span></div><div id="correlation-selection" aria-live="polite"></div><div id="correlation-results"></div><div id="correlation-detail" aria-live="polite"></div></section>`;}
function correlationSelection(m){
  if(!correlationPair)return '<p class="correlation-note">Click a cell to identify the two variables.</p>';
  const [i,j]=correlationPair,a=m.variables[i],b=m.variables[j];if(!a||!b)return '';
  const c=m.matrix[i][j];return `<div class="correlation-selection-card"><div><small>Row ${i+1}</small><strong>${esc(a.name)}</strong><span>${esc(a.tag)} · ${esc(a.unit||'Unit not supplied')}</span></div><b class="correlation-selection-cross">×</b><div><small>Column ${j+1}</small><strong>${esc(b.name)}</strong><span>${esc(b.tag)} · ${esc(b.unit||'Unit not supplied')}</span></div><div class="correlation-selection-value"><strong>r = ${c.r===null?'—':c.r.toFixed(3)}</strong><span>${c.n} matched samples${c.reason?' · '+esc(c.reason):''}</span></div></div>`;
}
function correlationDetail(m){if(!correlationPair)return '<p class="correlation-note">Select a cell to inspect its paired samples and scatter plot.</p>';const [i,j]=correlationPair,a=m.variables[i],b=m.variables[j];if(!a||!b)return '';const result=m.matrix[i][j];let plot='';if(result.points.length){const xs=result.points.map(p=>p[0]),ys=result.points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),x=v=>60+(v-xmin)/(xmax-xmin||1)*480,y=v=>170-(v-ymin)/(ymax-ymin||1)*145;
  plot=`<svg viewBox="0 0 600 220" class="correlation-scatter" role="img" aria-label="${esc(a.name)} versus ${esc(b.name)}"><path d="M60 25V170H540" fill="none" stroke="#7b8c97"/>${result.points.map(([vx,vy])=>`<circle cx="${x(vx)}" cy="${y(vy)}" r="2.5" fill="#326c97" opacity=".5"><title>${esc(a.tag)}: ${vx}; ${esc(b.tag)}: ${vy}</title></circle>`).join('')}<text x="60" y="185">${fmt(xmin)}</text><text x="540" y="185" text-anchor="end">${fmt(xmax)}</text><text x="52" y="170" text-anchor="end">${fmt(ymin)}</text><text x="52" y="30" text-anchor="end">${fmt(ymax)}</text><text x="300" y="209" text-anchor="middle">${esc(a.name)} (${esc(a.unit||'unit not supplied')})</text><text x="60" y="14">${esc(b.name)} (${esc(b.unit||'unit not supplied')})</text></svg>`;}
  return `<div class="correlation-pair"><h3>${esc(a.name)} × ${esc(b.name)}</h3><p>r = <b>${result.r===null?'—':result.r.toFixed(3)}</b> · n = ${result.n} matched samples${result.reason?' · '+result.reason:''}${result.n>=3&&result.n<10?' · Few paired samples':''}</p>${plot}</div>`;
}
function refreshCorrelations(){const m=correlationModel(),root=$('#correlation-results');if(!root)return;const scroll=root.querySelector('.correlation-table-wrap'),left=scroll?.scrollLeft||0,top=scroll?.scrollTop||0;root.innerHTML=m.times.length&&m.variables.length?`<div class="correlation-table-wrap"><table class="correlation-table"><thead><tr><th>Variable</th>${m.variables.map((v,i)=>`<th title="${esc(v.name)} · ${esc(v.tag)}">${i+1}</th>`).join('')}</tr></thead><tbody>${m.variables.map((v,i)=>`<tr><th title="${esc(v.tag)}">${i+1}. ${esc(v.name)}<small>${esc(v.tag)}</small></th>${m.matrix[i].map((c,j)=>`<td><button type="button" data-correlation="${i},${j}" aria-pressed="${correlationPair?.[0]===i&&correlationPair?.[1]===j}" style="background:${correlationColor(c.r)};color:${c.r!==null&&Math.abs(c.r)>.6?'white':'#263747'}" title="${esc(v.name)} × ${esc(m.variables[j].name)}: ${c.r===null?c.reason:'r = '+c.r.toFixed(3)}; n = ${c.n}" aria-label="${esc(v.name)} and ${esc(m.variables[j].name)}, ${c.r===null?c.reason:c.r.toFixed(3)}, ${c.n} matched samples">${c.r===null?'—':c.r.toFixed(2)}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No readings in this date range.</div>';const next=root.querySelector('.correlation-table-wrap');if(next){next.scrollLeft=left;next.scrollTop=top;}root.querySelectorAll('[data-correlation]').forEach(button=>button.onclick=()=>{correlationPair=button.dataset.correlation.split(',').map(Number);root.querySelectorAll('[data-correlation]').forEach(cell=>cell.setAttribute('aria-pressed',String(cell===button)));$('#correlation-selection').innerHTML=correlationSelection(m);$('#correlation-detail').innerHTML=correlationDetail(m);});$('#correlation-selection').innerHTML=correlationSelection(m);$('#correlation-detail').innerHTML=correlationDetail(m);$('#correlation-clock').textContent=Number.isFinite(m.end)?dateLabel(new Date(m.end).toISOString())+' UTC':'No samples';$('#correlation-time').max=Math.max(0,m.times.length-1);$('#correlation-time').disabled=!m.times.length;$('#correlation-time').value=Math.max(0,m.times.indexOf(stamp||m.times.at(-1)));$('#correlation-play').disabled=m.times.length<2;$('#correlation-play').textContent=correlationTimer?'Pause':'Play recording';}
function bindCorrelations(){
  if(page!=='correlations')return;refreshCorrelations();
  const changeRange=()=>{stopCorrelations();const from=$('#correlation-start').value,to=$('#correlation-end').value,error=$('#correlation-range-error');if(!from||!to||from>to){error.textContent='Choose both dates, with the end date on or after the start date.';$('#correlation-play').textContent='Play recording';$('#correlation-play').disabled=true;return;}error.textContent='';correlationStart=from;correlationEnd=to;stamp='';refreshCorrelations();};
  $('#correlation-start').onchange=changeRange;$('#correlation-end').onchange=changeRange;
  $('#correlation-time').oninput=e=>{stopCorrelations();stamp=correlationRange().times[Number(e.target.value)]||'';refreshCorrelations();};
  $('#correlation-latest').onclick=()=>{stopCorrelations();stamp='';refreshCorrelations();};
  $('#correlation-play').onclick=()=>{if(correlationTimer){stopCorrelations();refreshCorrelations();return;}const times=correlationRange().times;if(times.length<2)return;if(!times.includes(stamp)||stamp===times.at(-1))stamp=times[0];correlationTimer=setInterval(()=>{if(page!=='correlations'){stopCorrelations();return;}const t=correlationRange().times,i=t.indexOf(stamp);stamp=t[Math.min(i+1,t.length-1)]||'';if(stamp===t.at(-1)||!t.length)stopCorrelations();refreshCorrelations();},1000);refreshCorrelations();};
}
